-- Invoices are generated by the billing system and are read-only for tenants.
CREATE TABLE organization_invoices (
    id BIGINT NOT NULL AUTO_INCREMENT,

    organization_id BIGINT NOT NULL,

    invoice_number VARCHAR(50) NOT NULL,

    billing_month DATE NOT NULL,

    amount DECIMAL(14, 2) NOT NULL,

    currency VARCHAR(3) NOT NULL,

    status VARCHAR(20) NOT NULL DEFAULT 'ISSUED',

    payment_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',

    issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),

    CONSTRAINT uk_invoice_number
        UNIQUE (invoice_number),

    CONSTRAINT uk_invoice_organization_month
        UNIQUE (organization_id, billing_month),

    CONSTRAINT fk_invoice_organization
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE RESTRICT,

    CONSTRAINT chk_invoice_amount
        CHECK (amount >= 0)
);
